def encode(message):
    result = []
    vowels = 'aeiou'
    for char in message:
        if char.isalpha():
            # Swap case
            if char.islower():
                swapped = char.upper()
            else:
                swapped = char.lower()
            # Replace vowels
            if swapped in vowels:
                # Find the next vowel two places ahead
                index = vowels.index(swapped)
                new_index = (index + 2) % len(vowels)
                new_vowel = vowels[new_index]
                result.append(new_vowel)
            else:
                result.append(swapped)
        else:
            result.append(char)
    return ''.join(result)

