def permutation_coefficient(n, k):  
    if k > n:  
        return 0  
    if k == 0:  
        return 1  
    # Initialize a 2D array for DP  
    dp = [[0] * (k + 1) for _ in range(n + 1)]  
    # Base case: P(n, 0) = 1  
    for i in range(n + 1):  
        dp[i][0] = 1  
    # Fill the DP table  
    for i in range(1, n + 1):  
        for j in range(1, k + 1):  
            dp[i][j] = dp[i - 1][j] + j * dp[i - 1][j - 1]  
    return dp[n][k]

